# 수용 영역: r_out = r_in + (k-1)*j_in,  j_out = j_in*s  (j = 입력 한 칸 간격)
def rf(layers, full):
    r, j, out = 1, 1, []
    for name, k, s in layers:
        if k == "all":                          # 전역 평균 풀링 = 축 전체
            r = full
        else:
            r, j = r + (k - 1) * j, j * s
        out.append((name, r))
    return out
conv, pool, gap = ("conv3", 3, 1), ("pool4", 4, 4), ("GAP", "all", 1)
space = rf([conv, pool, conv, gap], 64)
plans = {
    "late":  rf([("conv", 1, 1), ("pool", 1, 1), ("conv", 1, 1), gap], 20),
    "early": rf([("conv", 20, 1), ("pool", 1, 1), ("conv", 1, 1), gap], 20),
    "3D":    rf([conv, pool, conv, gap], 20),
}
for k, tl in plans.items():
    print(f"{k:5s}", [f"{t}x{s}x{s}" for (_, t), (_, s) in zip(tl, space)])
